from pathlib import Path
import json
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0561-B{k:04d}']=t
p(4,'《邪恶之书》，《泰拉伪经》，成书年代不详。')
p(6,'阿尔法军团在大远征早期也被称为幽灵军团，是最初二十个星际战士军团中的第二十军团。他们在荷鲁斯之乱期间背叛帝皇，成为混沌星际战士。早在投向混沌之前，阿尔法军团就以行事最隐秘著称。他们守得最严的秘密，是自己拥有两位原体：阿尔法瑞斯与孪生兄弟欧米伽，两人有时合称“阿尔法瑞斯·欧米伽”。军团之外，只有极少数人知道此事。')
p(8,'阿尔法军团的老兵精通渗透与秘密行动，善于在不暴露身份、不直接开战的情况下，操纵局势向有利于自身的方向发展。他们也曾伪装成忠诚派星际战士。军中还包括被称为“特工”的普通人类。')
p(20,'混沌立场：各异，既有暗中忠于帝皇者，也有不效忠混沌者，以及信奉混沌无分者；多数势力会使用恶魔与混沌巫师。')
p(43,'鳞牙、蛇形灾祸、巨蛇之牙、阴影众、蔽影之手、欺骗之子、九头蛇之子、毒液之子、魂牙、破碎智灵、隐秘之刃。')
p(51,'作为初次建军中最后建立的军团，第二十军团据称直到阿尔法瑞斯被寻回前数十年才开始组建；另一些记载却称，其雏形早已存在。记述者对建军时间的记录似乎彼此矛盾。无论如何，军团应是在帝皇密令下秘密建立，连基因种子资料也被列为绝密。与火蜥蜴、太空野狼一样，第二十军团大体独立于其他阿斯塔特军团进行组建，可能各有特定使命；一些资料将这三个军团隐晦地合称“三叶草”。第二十军团最早的已知行动，是在泰拉及其以外针对帝国之敌实施绑架、定点突袭与暗杀。这支神秘的特种部队只以“阿尔法”为代号，不接受当时任何已寻回原体的指挥。出于未知原因，帝皇没有批准迅速扩大阿尔法部队的基因种子群体，将其兵力限制在约一千至两千名军团战士。有人怀疑，他们的基因种子存在帝皇无法修复的潜在缺陷；也有人推测，帝皇刻意将军团单独保留，准备日后进行其他军团从未接受过的特殊基因强化。')
p(55,'大远征期间，军团几乎从帝国档案中消失，但仍有零星记录，提到小股阿尔法部队远离远征前线执行特殊任务。他们显然是阿斯塔特，却不佩戴军团徽记，有时甚至冒用其他军团的旗号。其任务包括暗杀、欺骗、间谍活动、破坏与回收不明遗物，也会绑架反帝国组织的重要人物，并以不留目击者为原则。然而，“幽灵军团”的传闻依旧传遍银河。据说，这支部队会先用秘密行动与诡计不断消耗敌军，再从上百个方向发动大规模闪电突袭，称为“折磨”。阿尔法瑞斯本人的一份存疑自述则称，原体失散后不久，他其实就被帝皇在泰拉寻回，并从一开始便统率幽灵军团。彼时，除帝皇、马卡多及后来得知此事的康斯坦丁·瓦尔多外，无人知道他的存在。')
p(57,'冉丹灭绝战争期间，第二十军团的一名代表拜见莱昂·艾尔庄森。他自称阿尔法瑞斯，却承认军团原体尚未被寻回，只表示时机到来便会找到。这位“阿尔法瑞斯”提出援助雄狮对抗冉丹，希望将来拥立他为战帅。另一份相互冲突的记载认为，他可能就是真正的阿尔法瑞斯；还有一种说法称，他只是以此为掩护，进入冉丹战区寻找失散已久的欧米伽。无论真相如何，他表示，比起罗伯特·基里曼等人，第二十军团更愿拥护艾尔庄森出任战帅，因为双方对战争与保密抱有相似看法。即便身为原体，雄狮当时也并不确知第二十军团的存在，只听闻过“幽灵军团”的传说。')
p(59,'阿尔法瑞斯与欧米伽公开接掌军团时，这支年轻部队充满热情，一心遵循原体的教导。阿尔法瑞斯相信，保密与灵活应变是制胜之道，要求军团将相关技法贯彻于训练和实战。其大远征胜绩，无不涉及诡计、误导，或迅速而出人意料的机动。这些胜利需要极高的技巧与投入，阿尔法军团也很快变得封闭自矜。这份武人的骄傲使他们屡屡与其他军团发生冲突，尤其是帝国之拳、极限战士与死亡守卫。午夜领主的康拉德·科兹更公开抨击他们的战术，称其为“披着谎言裹尸布的罪人”。千子则悄然疏远他们，尽量避免往来，原因不明。不过，阿尔法军团与荷鲁斯的影月苍狼，以及黑暗天使、钢铁之手共同作战时，却能合作顺利，未生事端。')
p(61,'与罗伯特·基里曼发生争执后，阿尔法军团更加执着于自己偏爱的战法，大体背离帝国的常规作战方式，刻意制造越来越辉煌的胜绩，以证明自身理念，哪怕正面攻击本会更加高效。最臭名昭著的例子发生在特斯特拉主星：军团本可迅速占领首都、迫使全星投降，却故意让敌军筑垒固守，再以种种手段逐一瓦解其防御。守军经历整整一周看似偶发的灾祸与残酷伏击，伤亡达九成，最终投降。据说，当有人问为何不采用更简单的策略时，阿尔法瑞斯回答：“那样未免太容易了。”此役招来几乎所有兄弟原体的责难，只有一向欣赏他的荷鲁斯赞许军团的本领。大远征后期，阿尔法军团退入帝国边境外的空旷星域。')
p(63,'从这些帝国记录来看，阿尔法军团为何在战帅与混沌结盟时投向荷鲁斯，似乎不难理解：对自身武艺的骄傲，加上阿尔法瑞斯疏远其他兄弟、唯独亲近荷鲁斯，仿佛共同促成了堕落。然而，还有另一种说法。荷鲁斯之乱爆发前不到两年，异形组织“密教”接触了阿尔法瑞斯与欧米伽，向他们展示即将到来的叛乱及其他未来景象，并传授混沌本质的知识。按照这些预示，叛乱只会有两种结局：若帝皇获胜，人类将在衰败中延续一两万年，最终与银河一同被混沌吞噬；若荷鲁斯获胜，人类则将在两代之内灭亡，并把混沌诸神一同拖入毁灭，从而保全银河其他种族。密教要求阿尔法军团接受最艰难的使命：投向荷鲁斯，确保混沌最终灭亡。阿尔法瑞斯与欧米伽似乎答应了。')
p(64,'The Horus Heresy 荷鲁斯之乱')
p(66,'伊斯塔万三号遭病毒轰炸后，仍被视为忠诚的阿尔法军团奉帝皇之命，与其他军团一同前往伊斯塔万五号，摧毁荷鲁斯的据点。他们被编入第二波攻势，却转而袭击了第一波进攻的忠诚派。')
p(70,'暗鸦守卫指挥官布兰·涅夫抵达伊斯塔万五号，接应原体科拉克斯及其他忠诚派残部时，阿尔法军团暗中帮助他们撤离，甚至杀死一艘吞世者战斗驳船的指挥官，以免该舰拖住占优势的暗鸦守卫舰队。阿尔法军团的药剂师精通面部移植，将阵亡暗鸦守卫的面容移植到自己战士身上；再凭借吞食死者大脑获得的知识，三名阿尔法战士成功混入暗鸦守卫。之后，又有约五十名伪装成暗鸦守卫的战士前来支援。欧米伽成功取回了渗透者获取的情报，但这些潜伏者最终都被暗鸦守卫杀死。得知此事后，荷鲁斯命以泽凯尔·阿巴顿不惜代价，找出潜藏在自己军团中的阿尔法特工。')
p(72,'荷鲁斯之乱期间，阿尔法军团很早便脱离叛军主力，没有直接进攻泰拉，而是实施一连串迟滞行动，牵制帝国援军。较早的一次行动发生在香德克斯星系，他们企图困住白疤，却被察合台可汗设法摆脱。阿尔法瑞斯与欧米伽难以捉摸的意图，也在此显露：荷鲁斯本命他们争取白疤，但阿尔法舰队却采取敌对行动，先封锁白疤，直到对方收到罗格·多恩揭露荷鲁斯背叛的消息，再仿佛刻意挑起战斗。而消息之所以能够送达，恰是因为欧米伽派人摧毁了由阿尔法部队控制、阻断白疤通讯的塔式阵列。阿尔法军团，至少其中一部分人，便以如此隐晦的方式，确保察合台可汗站在帝皇一边。连军团自身也会成为计谋的牺牲品：阿尔法瑞斯曾操纵沙德拉克·梅杜森麾下的破碎军团突击部队，消灭一支看似忠于帝皇的阿尔法秘密小组。')
p(74,'Alpha Legion unknown Terminator Strike Leader who led the initial orbital raid on the Panopticon Complex of the Paramar Terminus facility 阿尔法军团一名身份不详的终结者突击指挥官，曾率领首轮轨道突袭，攻击帕拉马尔终点站的全视综合设施')
n.update({'A0561-B0004':'The Book of Malignancies 暂译邪恶之书；原译恶性之书未能表达此处著作名称语气。成书年代不详照录。','A0561-B0006':'原文是军团外只有少数人知晓，不是少数其他军团知晓。','A0561-B0043':'Splintered Sentients 指破碎的智慧存在，原译裂痕情感混淆 sentient 与 sentiment，暂译破碎智灵；其余战帮名保持对应。','A0561-B0051':'Remembrancers 是记述者，不是回忆录；无人向已寻回原体领命的关系也已修复。军团成立年代多种说法均照录。','A0561-B0055':'本段明确将阿尔法瑞斯自述标为存疑，不因是人物自述而改写为确认史实。','A0561-B0063':'密教所展示的两种结局是该组织的预言；原译遗漏人类将在衰败中延续，并把混沌共同灭亡误译成被遗忘。','A0561-B0070':'superior 指舰队实力占优，不是行政级别更高；杀死舰长的目的为排除追阻，不是使暗鸦守卫被耽搁。','A0561-B0072':'Pylon 在所给句中未说明是电缆塔，暂按塔式阵列处理；cell 指秘密行动小组，不是整个军团。','A0561-B0074':'Paramar Terminus 原译终点战为错字，修正终点站；Panopticon Complex 暂译全视综合设施，所给句未确认其为监狱。'})
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
